package at.foama.wien;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.android.controller.ActivityController;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) @LooperMode(LooperMode.Mode.PAUSED)
public class WatchPowerSaverTest {
 @Test public void optionalModeUsesTwentyAndTwentyFivePercentHysteresis(){WatchPowerSaver p=new WatchPowerSaver(false,false);assertFalse(p.update(10));assertFalse(p.active);p.enabled=true;assertTrue(p.update(19));assertTrue(p.active);assertFalse(p.update(20));assertFalse(p.update(24));assertTrue(p.update(25));assertFalse(p.active);assertFalse(p.update(20));assertTrue(p.update(19));p.enabled=false;assertTrue(p.update(19));assertFalse(p.active);}
 @Test public void savingModeSlowsWorkWithoutChangingFreshnessRulesAndExplicitLocationStillWorks(){WatchPowerSaver p=new WatchPowerSaver(true,false);p.update(19);assertEquals(90000,p.departureInterval());assertEquals(30000,p.renderInterval());assertFalse(p.locationDue(299999,0,false));assertTrue(p.locationDue(300000,0,false));assertTrue(p.locationDue(1,0,true));assertTrue(p.locationDue(1,-1,false));assertFalse(WearPolicy.reliable(120001,0,5,false));p.update(25);assertEquals(30000,p.departureInterval());assertEquals(10000,p.renderInterval());assertTrue(p.locationDue(1,0,false));}
 private TextView find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return (TextView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView t=find(((ViewGroup)v).getChildAt(i),text);if(t!=null)return t;}return null;}
 private void click(MainActivity app,String text){View v=find(app.getWindow().getDecorView(),text);assertNotNull(text,v);while(!v.isClickable()&&v.getParent() instanceof View)v=(View)v.getParent();assertTrue(v.performClick());}
 @Test public void lowBatteryExplainsOptInAndRecoveryReturnsToNormalWithoutBackgroundWork(){
  RuntimeEnvironment.getApplication().getSharedPreferences("foama",0).edit().clear().commit();ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).create().start();MainActivity app=c.get();try{app.repo.nextFetchElapsed=Long.MAX_VALUE;c.resume();app.applyBattery(19);assertFalse(app.powerSaver.enabled);assertFalse(app.powerSaver.active);click(app,"Akku sparen?");click(app,"Unter 20 % aktivieren");assertTrue(app.powerSaver.active);assertTrue(app.repo.prefs.getBoolean("ultraBattery",false));app.applyBattery(25);assertFalse(app.powerSaver.active);assertTrue(app.powerSaver.enabled);app.returnHome();assertNotNull(find(app.getWindow().getDecorView(),"Akku erholt · wieder Normalbetrieb."));c.pause();app.sendBroadcast(new Intent(Intent.ACTION_BATTERY_CHANGED).putExtra(BatteryManager.EXTRA_LEVEL,10).putExtra(BatteryManager.EXTRA_SCALE,100));org.robolectric.Shadows.shadowOf(Looper.getMainLooper()).idle();assertFalse(app.active);assertFalse(app.powerSaver.active);assertTrue(org.robolectric.Shadows.shadowOf((android.location.LocationManager)app.getSystemService(Context.LOCATION_SERVICE)).getLocationUpdateListeners().isEmpty());}finally{c.stop().destroy();}
 }
}
